(() => {
  const v = Math.round(
    collections.dashboard_box_3.data?.[0]?.weekly_variation_seconds ?? 0
  );

  if (v === 0) return '0 sec';

  const abs = Math.abs(v);

  const formatted =
    abs < 60
      ? abs + ' sec'
      : Math.floor(abs / 60) + ' min' + (abs % 60 ? ' ' + (abs % 60) + ' sec' : '');

  return v > 0 ? '+' + formatted : '-' + formatted;
})()

