const items = variables['418228f5-700a-4091-9da4-97a515db4eb3'] || [];

const activeSchoolId = Number(variables['88e24ee8-385c-44bd-90a8-84882b90688a']);

const currentSubject = variables['f931b446-eb2b-4e6e-ac7d-626440f874cd'];

const currentSubjectExists = items.some(item =>
  Number(item?.school_id) === activeSchoolId &&
  String(item?.subject || '').trim() === String(currentSubject || '').trim()
);

if (currentSubjectExists) {
  return currentSubject;
}

return items.find(item =>
  Number(item?.school_id) === activeSchoolId
)?.subject || null;
